     "summary": "9月9日(星期三)，今日报刊头条主要内容精华如下： 中国证券报 聚焦两大议题 券商中期业绩说明会透露这些信号 数据显示，截至9月8日中国证券报记者发稿时，已有16家上市券商召开2026年半年度业绩说明会。本周，还将有中国银河、国金证券、东吴证券等券商召开半年度业绩说明会。从投资者提问内容看，未来券商业绩能否延续高增长态势、券商如何进一步强化自身竞争优势等被频繁问及。 券商齐聚投洽会 全链条服务双向投资 国际化版图再扩张 9月8日，第二十六届中国国际投资贸易洽谈会在厦门国际博览",
