     "time": "09-09 04:56",
     "ts": 1788900991,
     "summary": "调查数据显示，欧佩克（OPEC）原油产量8月大幅下滑，结束连续两个月的复苏势头。该组织最大产油国沙特的产量受到两条石油出口通道均面临威胁的影响。 调查显示，欧佩克成员国8月原油供应量较前一个月减少90万桶/日，平均降至1991万桶/日。其中，沙特产量下降超过100万桶/日，伊拉克和委内瑞拉产量增加，部分抵消了这一降幅。 欧佩克产量此前在6月和7月出现部分反弹，当时产油国设法将原油通过波斯湾运出。但如今产量再度下滑，凸显出美伊之间新一轮行动所带来的影响，持续长达六个月的冲突仍未",
     "source": "东方财富资讯",
     "agenda_layer": "market",
     "language": "zh",
